"""
i18n.py — বাংলা/English bilingual support

প্রতিটি ইউজারের ভাষা পছন্দ st.session_state["language"]-এ থাকে ('bn' নয়তো 'en'),
লগইনের সময় app_users.language থেকে লোড হয় (auth._complete_login)।

নতুন key যোগ করলে LANG_BN আর LANG_EN দুটোতেই যোগ করতে হবে — কোনো ভাষায়
key না পাওয়া গেলে t() বাংলায় fallback করে, বাংলাতেও না থাকলে raw key
ফেরত দেয় (crash করে না) — তাই ধাপে ধাপে (মডিউল অনুযায়ী) অনুবাদ যোগ করা
নিরাপদ, বাকি অংশ ভেঙে যায় না।
"""

