WEEKDAYS = {
    "bn": ["সোমবার", "মঙ্গলবার", "বুধবার", "বৃহস্পতিবার", "শুক্রবার", "শনিবার", "রবিবার"],
    "en": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
}
MONTHS = {
    "bn": ["জানুয়ারি", "ফেব্রুয়ারি", "মার্চ", "এপ্রিল", "মে", "জুন",
           "জুলাই", "আগস্ট", "সেপ্টেম্বর", "অক্টোবর", "নভেম্বর", "ডিসেম্বর"],
    "en": ["January", "February", "March", "April", "May", "June",
           "July", "August", "September", "October", "November", "December"],
}


def current_lang() -> str:
    lang = st.session_state.get("language", "bn")
    return lang if lang in LANGS else "bn"


def t(key: str, **kwargs) -> str:
    lang = current_lang()
    template = LANGS[lang].get(key) or LANG_BN.get(key, key)
    return template.format(**kwargs) if kwargs else template


def weekday_name(idx: int) -> str:
    return WEEKDAYS[current_lang()][idx]


def month_name(idx: int) -> str:
    return MONTHS[current_lang()][idx]
